   Tokens first, then base, then components in page order. Selectors are kept
   to single classes so nothing has to fight for specificity. */

:root {
  --paper: #F2F5F2;
  --panel: #FFFFFF;
  --ink: #142A2B;
  --ink-soft: #46605F;
  --line: #D3DDD9;
  --mist: #E7EDEA;

  --teal: #1D6B66;
  --teal-deep: #124845;
  --teal-tint: #DFEEEB;

  --amber: #E9A93C;
  --amber-tint: #FBEFD4;
  --amber-ink: #6B4A08;

  --rose: #C4463A;
  --rose-tint: #F8E4E1;

  --display: "Avenir Next", Avenir, "TeX Gyre Adventor", "Century Gothic", Poppins, "URW Gothic", "Segoe UI", sans-serif;
  --body: Inter, "Segoe UI", system-ui, -apple-system, Roboto, "Helvetica Neue", Arial, sans-serif;

  --wrap: 1120px;
  --gutter: 24px;
  --r-control: 6px;
  --r-bubble: 18px;
}

*, *::before, *::after { box-sizing: border-box; }

html { scroll-behavior: smooth; }
@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *::before, *::after { transition: none !important; animation: none !important; }
}

body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--body);
  font-size: 17px;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

h1, h2, h3 {
  font-family: var(--display);
  font-weight: 700;
  line-height: 1.12;
  letter-spacing: -0.015em;
  margin: 0 0 0.5em;
  text-wrap: balance;
}
h1 { font-size: clamp(2.25rem, 1.3rem + 3.6vw, 3.6rem); letter-spacing: -0.025em; }
h2 { font-size: clamp(1.7rem, 1.2rem + 1.6vw, 2.35rem); }
h3 { font-size: 1.25rem; line-height: 1.3; letter-spacing: -0.005em; }
p { margin: 0 0 1em; max-width: 62ch; }
a { color: var(--teal); text-decoration-thickness: 1px; text-underline-offset: 0.15em; }
ul, ol { margin: 0; padding: 0; }
strong { font-weight: 600; }
figure { margin: 0; }

:focus-visible {
  outline: 3px solid var(--amber);
  outline-offset: 3px;
}

.wrap {
  max-width: var(--wrap);
  margin: 0 auto;
  padding-left: var(--gutter);
  padding-right: var(--gutter);
}

.skip {
  position: absolute; left: 8px; top: -60px;
  background: var(--ink); color: var(--paper);
  padding: 8px 12px; border-radius: var(--r-control); z-index: 10;
}
.skip:focus { top: 8px; }

/* Buttons */
.btn {
  display: inline-block;
  background: var(--teal);
  color: #fff;
  font-family: var(--display);
  font-weight: 700;
  font-size: 1.0625rem;
  line-height: 1;
  padding: 16px 22px;
  border-radius: var(--r-control);
  border: 0;
  text-decoration: none;
  cursor: pointer;
  transition: background-color 120ms ease;
}
.btn:hover { background: var(--teal-deep); }
.btn--small { font-size: 0.9375rem; padding: 11px 16px; }
.btn--big { font-size: 1.2rem; padding: 20px 28px; }

.link-quiet {
  color: var(--ink);
  font-weight: 500;
}

